"""Min-heap from scratch with all standard operations.

Supports: insert, extract_min, peek, decrease_key, delete,
build_heap, merge, and standard dunder methods.
"""


class MinHeap:
    __slots__ = ("_heap", "_pos")

    def __init__(self, items=None):
        self._heap: list[list] = []  # [key, value] pairs
        self._pos: dict = {}  # value -> index in _heap
        if items is not None:
            self.build_heap(items)

    # ── Query ───────────────────────────────────────────────────────────

    def peek(self):
        """Return (key, value) of the minimum element. O(1)."""
        if not self._heap:
            raise IndexError("peek from empty heap")
        return tuple(self._heap[0])

    def __len__(self) -> int:
        return len(self._heap)

    def __bool__(self) -> bool:
        return bool(self._heap)

    def __contains__(self, value) -> bool:
        return value in self._pos

    # ── Insert ──────────────────────────────────────────────────────────

    def insert(self, value, key) -> None:
        """Insert an item with the given key (priority). O(log n)."""
        idx = len(self._heap)
        self._heap.append([key, value])
        self._pos[value] = idx
        self._sift_up(idx)

    # ── Extract ─────────────────────────────────────────────────────────

    def extract_min(self):
        """Remove and return (key, value) of the minimum element. O(log n)."""
        if not self._heap:
            raise IndexError("extract from empty heap")
        self._swap(0, len(self._heap) - 1)
        key, value = self._heap.pop()
        del self._pos[value]
        if self._heap:
            self._sift_down(0)
        return (key, value)

    # ── Decrease key ────────────────────────────────────────────────────

    def decrease_key(self, value, new_key) -> None:
        """Decrease the key of the given value. O(log n)."""
        if value not in self._pos:
            raise KeyError(f"value {value!r} not in heap")
        idx = self._pos[value]
        if new_key > self._heap[idx][0]:
            raise ValueError("new key is greater than current key")
        self._heap[idx][0] = new_key
        self._sift_up(idx)

    # ── Delete ──────────────────────────────────────────────────────────

    def delete(self, value) -> None:
        """Remove an arbitrary value from the heap. O(log n)."""
        if value not in self._pos:
            raise KeyError(f"value {value!r} not in heap")
        idx = self._pos[value]
        last = len(self._heap) - 1
        if idx != last:
            self._swap(idx, last)
            self._heap.pop()
            del self._pos[value]
            if idx < len(self._heap):
                parent = (idx - 1) // 2
                if idx > 0 and self._heap[idx][0] < self._heap[parent][0]:
                    self._sift_up(idx)
                else:
                    self._sift_down(idx)
        else:
            self._heap.pop()
            del self._pos[value]

    # ── Build heap ──────────────────────────────────────────────────────

    def build_heap(self, items) -> None:
        """Build a heap from an iterable of (value, key) pairs. O(n)."""
        self._heap = [[k, v] for v, k in items]
        self._pos = {v: i for i, (k, v) in enumerate(self._heap)}
        for i in range(len(self._heap) // 2 - 1, -1, -1):
            self._sift_down(i)

    # ── Merge ───────────────────────────────────────────────────────────

    def merge(self, other: "MinHeap") -> "MinHeap":
        """Return a new MinHeap containing elements from both heaps. O(n)."""
        combined = []
        for key, value in self._heap:
            combined.append((value, key))
        for key, value in other._heap:
            combined.append((value, key))
        return MinHeap(combined)

    # ── Internal helpers ────────────────────────────────────────────────

    def _swap(self, i, j) -> None:
        self._heap[i], self._heap[j] = self._heap[j], self._heap[i]
        self._pos[self._heap[i][1]] = i
        self._pos[self._heap[j][1]] = j

    def _sift_up(self, i) -> None:
        heap = self._heap
        while i > 0:
            parent = (i - 1) // 2
            if heap[i][0] < heap[parent][0]:
                self._swap(i, parent)
                i = parent
            else:
                break

    def _sift_down(self, i) -> None:
        heap = self._heap
        n = len(heap)
        while True:
            smallest = i
            left = 2 * i + 1
            right = 2 * i + 2
            if left < n and heap[left][0] < heap[smallest][0]:
                smallest = left
            if right < n and heap[right][0] < heap[smallest][0]:
                smallest = right
            if smallest != i:
                self._swap(i, smallest)
                i = smallest
            else:
                break


if __name__ == "__main__":
    h = MinHeap()
    h.insert("task_c", 30)
    h.insert("task_a", 10)
    h.insert("task_b", 20)
    h.insert("task_d", 40)

    print("peek:", h.peek())            # (10, 'task_a')
    print("len:", len(h))               # 4
    print("contains task_a:", "task_a" in h)  # True

    print("extract:", h.extract_min())  # (10, 'task_a')
    print("extract:", h.extract_min())  # (20, 'task_b')

    h.decrease_key("task_d", 5)
    print("after decrease_key(task_d, 5):")
    print("extract:", h.extract_min())  # (5, 'task_d')
    print("extract:", h.extract_min())  # (30, 'task_c')

    # build_heap
    h2 = MinHeap([("x", 50), ("y", 10), ("z", 30)])
    print("\nbuild_heap extract:", h2.extract_min())  # (10, 'y')

    # delete
    h3 = MinHeap([("a", 1), ("b", 2), ("c", 3)])
    h3.delete("b")
    print("after delete('b'), extract order:", end=" ")
    while h3:
        print(h3.extract_min(), end=" ")
    print()  # (1, 'a') (3, 'c')

    # merge
    h4 = MinHeap([("p", 10), ("q", 20)])
    h5 = MinHeap([("r", 5), ("s", 15)])
    merged = h4.merge(h5)
    print("merged extract order:", end=" ")
    while merged:
        print(merged.extract_min(), end=" ")
    print()  # (5, 'r') (10, 'p') (15, 's') (20, 'q')
